  const MapDraw = (() => {
    try {
      if (typeof require === 'function' && typeof module !== 'undefined') return require('./map-draw.js');
      return (typeof window !== 'undefined' ? window.__BE3_MAPDRAW__ : null);
    } catch (e) { return null; }
  })();

  /**
   * ★★ 第 76 窗口：形状点阵模块（`map-shapes.js`）。
   * 🔴 与 `MapDraw` 同款「require 优先 + 全局兜底」——
   *   浏览器里模块由 build 按顺序挂到全局（没有 `require`）；判据（Node）里直接 require。
   * ⚠️ 拿不到 ⇒ `lattice` 为空 ⇒ 渲染层退回「中心一枚 emoji」（不崩、不静默画错）。
   */
  const MapShapes = (() => {
    try {
      if (typeof require === 'function' && typeof module !== 'undefined') return require('./map-shapes.js');
      return (typeof window !== 'undefined' ? window.__BE3_MAPSHAPES__ : null);
    } catch (e) { return null; }
  })();

  /** 四类的规范名（**白名单** —— 认不出的一律当 `building`，绝不猜成「场景」） */
  const CLASSES = ['effect', 'scene', 'building', 'prop'];
  const CLASS_LABEL = {
    effect: '持续效果', scene: '大范围场景', building: '建筑 / 地形', prop: '可互动物件',
  };

  /** 层次序号（小 = 先画 = 在底下） */
