    const histMsgs2 = [];   /* 老路径不发历史（见上面的红字） */
    histMsgs2.forEach((m) => {
      if (!isObj(m)) return;
      const role = asText(m.role);
      if (role !== 'user' && role !== 'assistant' && role !== 'system') return;
      const o = { kind: 'history', role, content: applyPanelMacros(asText(m.content), c) };
      if (asText(m.name)) o.name = asText(m.name);
      if (Number.isFinite(Number(m.depth))) o.depth = Number(m.depth);
      parts.push(o);
    });
    /* ★★ 第 92 窗口：面板全量资料（老路径也发 —— 它是「AI 判定的事实」，不是选项） */
    if (panelText.trim()) parts.push({ kind: 'panel', role: 'system', content: panelText });
    /* 玩家行动：原样透传（`buildUserInput` 只削首尾空白），走 `user_input` 档 */
    const userFinal = applyPanelMacros(userInput, c);
    parts.push({ kind: 'user_input', role: 'user', content: userFinal });
    /**
     * ★★★ 第 103 窗口：老路径同样**按实际 parts 重写事实行**（见 `reconcileHistoryNote`）。
     * 🔴 老路径一定 0 段历史 ⇒ 那句话必须改成「没有附带」，
     *   否则「读了 2 楼但一楼没发」的请求里仍写着「已附带 2 楼」——
     *   这正是用户说的「空置发出去还是自带这玩意」最直观的证据。
     */
    reconcileHistoryNote(parts, Array.isArray(c.historyMessages) ? c.historyMessages.length : 0);
