      ok: true, reason: '', parts, byPreset: false,
      /* `gen` 给 `api.genToBodyFields` 映射成请求体字段（`maxContext` 会被排除） */
      gen: isObj(c.gen) ? c.gen : {},
      /* `preset` 只提供 `max_tokens` 的兜底来源（不编数字） */
      preset: isObj(c.preset) ? c.preset : {},
