        worldbookText: x.worldbookText,
        presetItems: x.presetItems,
        /* ★ 第 87 窗口：预览要能取到 `entry` 绑定的正文与变量表（否则预览里是空段） */
        playerPresetItems: x.playerPresetItems,
        vars: x.vars,
